function getDbConfig(config) {
  const {
    database: { host, port, credentials: { username } }
  } = config;
  return { host, port, username };
}

function mergeConfigs(defaults, overrides) {
  return {
    ...defaults,
    ...overrides,
    database: { ...defaults.database, ...overrides.database },
    features: [...new Set([...defaults.features, ...overrides.features])]
  };
}

function getUserDisplayName(user) {
  return user?.profile?.name ?? "Anonymous";
}

function generateReport(title, data) {
  const entries = Object.entries(data)
    .map(([key, value]) => `  ${key}: ${value}`)
    .join("\n");

  return `
=== ${title} ===
Generated: ${new Date().toLocaleDateString()}

${entries}

Total entries: ${Object.keys(data).length}
=== End Report ===
  `.trim();
}

